import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
format_phone = target.format_phone


def test_valid_10_digits():
    """10 digits should be formatted as (XXX) XXX-XXXX."""
    assert format_phone("1234567890") == "(123) 456-7890"


def test_another_valid():
    assert format_phone("9876543210") == "(987) 654-3210"


def test_all_zeros():
    assert format_phone("0000000000") == "(000) 000-0000"


def test_non_string_raises_typeerror():
    """Non-string input should raise TypeError."""
    try:
        format_phone(1234567890)
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_with_spaces_raises_valueerror():
    """String with spaces should raise ValueError."""
    try:
        format_phone("123 456 7890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_with_dashes_raises_valueerror():
    """String with separators should raise ValueError."""
    try:
        format_phone("123-456-7890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_country_code_raises_valueerror():
    """String with country code should raise ValueError."""
    try:
        format_phone("11234567890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_too_few_digits_raises_valueerror():
    """Missing digits should raise ValueError."""
    try:
        format_phone("123456789")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_empty_string_raises_valueerror():
    """Empty string should raise ValueError."""
    try:
        format_phone("")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_letters_raises_valueerror():
    """String with letters should raise ValueError."""
    try:
        format_phone("123456789a")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_parentheses_raises_valueerror():
    """String with parentheses should raise ValueError."""
    try:
        format_phone("(123)4567890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_none_raises_typeerror():
    """None should raise TypeError."""
    try:
        format_phone(None)
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_float_raises_typeerror():
    """Float should raise TypeError."""
    try:
        format_phone(1234567890.0)
        assert False, "Should have raised TypeError"
    except TypeError:
        pass

