import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
paginate = target.paginate


def test_page_1():
    """Page 1 starts at the first item."""
    assert paginate([1, 2, 3, 4, 5], 1, 2) == [1, 2]


def test_page_2():
    """Page 2 with per_page=2."""
    assert paginate([1, 2, 3, 4, 5], 2, 2) == [3, 4]


def test_page_beyond_end():
    """Pages beyond the end return an empty list."""
    assert paginate([1, 2, 3], 2, 1) == []


def test_exact_boundary():
    """Exactly fitting pages."""
    assert paginate([1, 2, 3, 4], 2, 2) == [3, 4]


def test_single_page_all_items():
    """All items fit on one page."""
    assert paginate([1, 2, 3], 1, 10) == [1, 2, 3]


def test_empty_list():
    """Empty list should return empty list."""
    assert paginate([], 1, 5) == []


def test_non_list_raises_typeerror():
    """Non-list input should raise TypeError."""
    try:
        paginate("not a list", 1, 5)
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_zero_page_raises_valueerror():
    """page=0 should raise ValueError since it must be positive."""
    try:
        paginate([1, 2], 0, 5)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_negative_page_raises_valueerror():
    """Negative page should raise ValueError."""
    try:
        paginate([1, 2], -1, 5)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_zero_per_page_raises_valueerror():
    """per_page=0 should raise ValueError."""
    try:
        paginate([1, 2], 1, 0)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_non_int_page_raises_typeerror():
    """Non-int page should raise TypeError."""
    try:
        paginate([1, 2], "1", 5)
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_non_int_per_page_raises_typeerror():
    """Non-int per_page should raise TypeError."""
    try:
        paginate([1, 2], 1, "5")
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_per_page_1():
    """per_page=1 returns one item per page."""
    assert paginate(["a", "b", "c"], 2, 1) == ["b"]


def test_far_beyond_page():
    """Very large page number returns empty list."""
    assert paginate([1], 999, 5) == []

