def test_two_same_length_words():
    """Two words of the same length should both appear in the bucket."""
    result = bucket_by_length(["hi", "no"])
    # Both should be in the bucket for length 2
    assert len(result.get(2, [])) == 2, "Should have both words in the length-2 bucket"


def test_single_word():
    """Single word should produce one bucket."""
    result = bucket_by_length(["hello"])
    assert result == {5: ["hello"]}


def test_mixed_lengths():
    """Words of different lengths should go to different buckets."""
    result = bucket_by_length(["a", "bb", "ccc"])
    assert result == {1: ["a"], 2: ["bb"], 3: ["ccc"]}


def test_empty_string():
    """Empty strings are allowed and belong to bucket 0."""
    result = bucket_by_length([""])
    assert result == {0: [""]}


def test_empty_list():
    """Empty list should return empty dict."""
    result = bucket_by_length([])
    assert result == {}


def test_preserves_order():
    """Input order within each bucket should be preserved."""
    result = bucket_by_length(["ab", "cd", "ef"])
    assert result.get(2) == ["ab", "cd", "ef"], "Order should be preserved within bucket"


def test_non_list_raises_typeerror():
    """Non-list input should raise TypeError."""
    try:
        bucket_by_length("not a list")
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_non_string_in_list_raises_typeerror():
    """List with non-string elements should raise TypeError."""
    try:
        bucket_by_length([123, "hello"])
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_multiple_same_length():
    """Multiple words of the same length should all be grouped."""
    result = bucket_by_length(["cat", "dog", "bat"])
    assert set(result.get(3, [])) == {"cat", "dog", "bat"}, "All three length-3 words should be present"


def test_three_in_bucket():
    """Three words of length 2 should all appear."""
    result = bucket_by_length(["hi", "no", "go"])
    assert result.get(2) == ["hi", "no", "go"], "All three should be in the bucket in order"

